5	// Add-a-client form. useState holds only what the user is currently typing; on submit it validates
6	// the email, and only a proper address POSTs and invalidates the ['clients'] key. A blank or
7	// malformed email surfaces client-form-email-error and never creates a row.
8	export function ClientForm() {
