15	    <form
16	      data-testid="client-form"
17	      onSubmit={(event) => {
18	        event.preventDefault();
19	        if (!isValidEmail(email)) {
20	          setEmailError(true);
21	          return;
22	        }
23	        setEmailError(false);
24	        create.mutate(
25	          { name, email },
26	          {
27	            onSuccess: () => {
28	              setName('');
29	              setEmail('');
30	            },
31	          },
32	        );
33	      }}
34	    >
35	      <input
36	        data-testid="client-form-name"
37	        placeholder="Name"
